def interval_overlap(a, b):
    a_start, a_end = min(a[0], a[1]), max(a[0], a[1])
    b_start, b_end = min(b[0], b[1]), max(b[0], b[1])
    start = max(a_start, b_start)
    end = min(a_end, b_end)
    if start <= end:
