import re

def mask_secrets(text):
    def repl(match):
        key = match.group(1)
        value = match.group(2)
        if re.search(r'password|token|key', key, re.IGNORECASE):
            return f"{key}=***"
        return match.group(0)

    # Pattern: key (non‑whitespace) followed by = and then any characters up to the next space or end of string
    pattern = r'(\S+)=([^ ]*)'
    return re.sub(pattern, repl, text)
```

