js-037.text:
I will implement `deepClone` by recursively traversing the input value, handling objects and arrays specially while using `Object.create(null)` for plain objects to avoid prototype pollution, and employing a `WeakMap` to track already‑cloned objects to break circular references. Edge cases such as `null`, primitives, `Date`, `RegExp`, and built‑in objects are handled with direct copying or appropriate constructors.

ANSWER:
```javascript
function deepClone(v) {
  if (v === null || typeof v !== 'object') return v;
  if (v instanceof Date) return new Date(v);
  if (v instanceof RegExp) return new RegExp(v);
  if (v instanceof Map) return new Map(Array.from(v, ([k, val]) => [deepClone(k), deepClone(val)]));
  if (v instanceof Set) return new Set(Array.from(v, val => deepClone(val)));
  if (v instanceof WeakMap || v instanceof WeakSet) return v;

  const seen = new WeakMap();

  function clone(obj) {
    if (obj === null || typeof obj !== 'object') return obj;
    if (seen.has(obj)) return seen.get(obj);

    let copy;
    if (Array.isArray(obj)) {
      copy = [];
      seen.set(obj, copy);
      for (let i = 0; i < obj.length; i++) {
        copy[i] = clone(obj[i]);
      }
    } else if (obj instanceof Date) {
      copy = new Date(obj);
    } else if (obj instanceof RegExp) {
      copy = new RegExp(obj);
    } else if (obj instanceof Map) {
      copy = new Map();
      seen.set(obj, copy);
      obj.forEach((val, key) => copy.set(clone(key), clone(val)));
    } else if (obj instanceof Set) {
      copy = new Set();
      seen.set(obj, copy);
      obj.forEach(val => copy.add(clone(val)));
    } else {
      copy = Object.create(Object.getPrototypeOf(obj));
